#!/usr/bin/env bash
# generate-release-notes.sh — Generate RELEASE_NOTES.md
# Usage: ./generate-release-notes.sh --version <semver> --name "<name>"

set -euo pipefail

VERSION=""
NAME=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    --version) VERSION="$2"; shift 2 ;;
    --name) NAME="$2"; shift 2 ;;
    *) echo "Unknown: $1"; exit 1 ;;
  esac
done

if [[ -z "$VERSION" || -z "$NAME" ]]; then
  echo "Usage: $0 --version <semver> --name \"<name>\""
  exit 1
fi

OUTPUT="RELEASE_NOTES-v${VERSION}.md"

# Extract changes from CHANGELOG
CHANGES=""
if [[ -f "CHANGELOG.md" ]]; then
  CHANGES=$(sed -n "/## \[$VERSION\]/,/^## /p" CHANGELOG.md | head -n -1)
fi

cat > "$OUTPUT" << NOTES
# Release v$VERSION — $NAME

**Date:** $(date '+%Y-%m-%d')

## What's New

$CHANGES

## Installation

\`\`\`bash
npm install package@latest
\`\`\`

## Full Changelog

See [CHANGELOG.md](./CHANGELOG.md)

---

*Generated by release-management workflow*
NOTES

echo "✅ Release notes generated: $OUTPUT"
